/*
 * The battery through the declarations of one legacy language: VB6, Visual FoxPro or PowerBuilder.
 * legacy_declarations.h, generated by declarations.py from the module the zip ships, gives every
 * function of the DLL the exact types that language passes (a Long for the response handle, a Byte
 * array or a blob for the UTF-8 request...). This program follows that language's module call by
 * call: UTF-8 bytes ending in a NUL, a response slot of the declared type, the response measured with
 * sunat_sdk_response_len, copied with sunat_sdk_response_copy and released with sunat_sdk_free.
 *
 *   battery <repository> [--dump <directory>] <case>...
 *
 * For every case, `build` its fixture and `sign` the result with the test certificate, and compare
 * DigestValue and SignatureValue with tests/vectors/<case>.signed.xml. --dump writes each response
 * as <case>.build.json and <case>.sign.json, for the VB6 JSON reader's test (json.ps1).
 *
 * On 32-bit Windows, built with /RTC1: a declaration whose stack differs from __stdcall stops it.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _WIN32
#include <windows.h>
#if defined(_M_IX86) || defined(__i386__)
#define LEGACY_STDCALL __stdcall
#else
#define LEGACY_STDCALL
#endif
#else
#include <dlfcn.h>
#define LEGACY_STDCALL
#endif

/* Only for the sizes the generated header asserts against; nothing is linked. */
#include "sunat_sdk.h"
#include "legacy_declarations.h"

static FN_call f_call;
static FN_response_len f_len;
static FN_response_copy f_copy;
static FN_free f_free;
static FN_version f_version;
static FN_abi_version f_abi;

static void fail(const char *what, const char *detail) {
    fprintf(stderr, "FAIL %s (%s): %.400s\n", what, LEGACY_LANGUAGE, detail ? detail : "");
    exit(1);
}

#ifdef _WIN32
static HMODULE library;
static FARPROC symbol(const char *name) {
    FARPROC found = GetProcAddress(library, name);
    if (!found) fail("export not found (decorated or missing)", name);
    return found;
}
static void open_library(void) {
    /* By name, as a Declare does: the DLL sits next to this program. */
    library = LoadLibraryA("sunat_sdk_ffi.dll");
    if (!library) fail("LoadLibrary sunat_sdk_ffi.dll", NULL);
}
#else
static void *library;
static void *symbol(const char *name) {
    void *found = dlsym(library, name);
    if (!found) fail("symbol not found", name);
    return found;
}
static void open_library(void) {
    const char *path = getenv("SUNAT_SDK_LIBRARY");
    library = dlopen(path ? path : "libsunat_sdk_ffi.so", RTLD_NOW);
    if (!library) fail("dlopen", dlerror());
}
#endif

static void load(void) {
    open_library();
    f_call = (FN_call)symbol(SYMBOL_call);
    f_len = (FN_response_len)symbol(SYMBOL_response_len);
    f_copy = (FN_response_copy)symbol(SYMBOL_response_copy);
    f_free = (FN_free)symbol(SYMBOL_free);
    f_version = (FN_version)symbol(SYMBOL_version);
    f_abi = (FN_abi_version)symbol(SYMBOL_abi_version);
}

/* One call as the language's module makes it; returns the response's bytes, NUL-terminated. */
static char *call(const char *request, int32_t expected, const char *what) {
    size_t size = strlen(request);
    char *bytes = malloc(size + 1);
    PTE_call_1 slot = 0;
    RET_call status;
    size_t length;
    char *buffer;
    if (!bytes) fail("malloc", what);
    memcpy(bytes, request, size + 1);
    status = f_call((ARG_call_0)(uintptr_t)bytes, &slot);
    free(bytes);
    if (slot == 0) fail(what, "no response");

    length = (size_t)f_len((ARG_response_len_0)slot);
    buffer = malloc(length + 1);
    if (!buffer) fail("malloc", what);
    if (length > 0 && (int32_t)f_copy((ARG_response_copy_0)slot, (ARG_response_copy_1)(uintptr_t)buffer,
                                      (ARG_response_copy_2)(length - 1)) != SUNAT_SDK_BUFFER_TOO_SMALL)
        fail(what, "a short buffer was not refused");
    if ((int32_t)f_copy((ARG_response_copy_0)slot, (ARG_response_copy_1)(uintptr_t)buffer,
                        (ARG_response_copy_2)(length + 1)) != SUNAT_SDK_OK)
        fail(what, "sunat_sdk_response_copy");
    f_free((ARG_free_0)slot);
    buffer[length] = '\0';
    if ((int32_t)status != expected) fail(what, buffer);
    return buffer;
}

static char *read_file(const char *path) {
    FILE *file = fopen(path, "rb");
    long size;
    char *text;
    if (!file) fail("open", path);
    fseek(file, 0, SEEK_END);
    size = ftell(file);
    fseek(file, 0, SEEK_SET);
    text = malloc((size_t)size + 1);
    if (!text || fread(text, 1, (size_t)size, file) != (size_t)size) fail("read", path);
    text[size] = '\0';
    fclose(file);
    return text;
}

static void write_file(const char *path, const char *text) {
    FILE *file = fopen(path, "wb");
    if (!file || fwrite(text, 1, strlen(text), file) != strlen(text)) fail("write", path);
    fclose(file);
}

static char *concat(const char *a, const char *b, const char *c, const char *d, const char *e) {
    const char *parts[5];
    size_t total = 1, i;
    char *out;
    parts[0] = a; parts[1] = b; parts[2] = c; parts[3] = d; parts[4] = e;
    for (i = 0; i < 5; i++) total += parts[i] ? strlen(parts[i]) : 0;
    out = malloc(total);
    if (!out) fail("malloc", NULL);
    out[0] = '\0';
    for (i = 0; i < 5; i++)
        if (parts[i]) strcat(out, parts[i]);
    return out;
}

/* The JSON string literal (quotes included) of `"key":` in an object written by serde_json. */
static char *json_token(const char *json, const char *key) {
    char *pattern = concat("\"", key, "\":\"", NULL, NULL);
    const char *start = strstr(json, pattern);
    const char *end;
    char *token;
    free(pattern);
    if (!start) fail("key not in response", key);
    start += strlen(key) + 3;
    for (end = start + 1; *end && *end != '"'; end++)
        if (*end == '\\') end++;
    if (*end != '"') fail("unterminated string", key);
    token = malloc((size_t)(end - start) + 2);
    memcpy(token, start, (size_t)(end - start) + 1);
    token[end - start + 1] = '\0';
    return token;
}

/* A string value without escapes (base64), quotes removed. */
static char *json_plain(const char *json, const char *key) {
    char *token = json_token(json, key);
    size_t len = strlen(token);
    memmove(token, token + 1, len - 2);
    token[len - 2] = '\0';
    return token;
}

static char *element_text(const char *xml, const char *element) {
    char *open = concat("<", element, ">", NULL, NULL);
    const char *start = strstr(xml, open);
    const char *end;
    char *text;
    if (!start) fail("element missing", element);
    start += strlen(open);
    free(open);
    end = strchr(start, '<');
    text = malloc((size_t)(end - start) + 1);
    memcpy(text, start, (size_t)(end - start));
    text[end - start] = '\0';
    return text;
}

/* A path as a JSON string body: Windows paths come with backslashes. */
static char *json_escape(const char *text) {
    char *out = malloc(strlen(text) * 2 + 1);
    char *write = out;
    for (; *text; text++) {
        if (*text == '\\' || *text == '"') *write++ = '\\';
        *write++ = *text;
    }
    *write = '\0';
    return out;
}

static void run_case(const char *repo, const char *cert, const char *key, const char *dump, const char *name) {
    char *fixture = read_file(concat(repo, "/fixtures/", name, ".json", NULL));
    char *built = call(concat("{\"command\":\"build\",\"input\":", fixture, "}", NULL, NULL), SUNAT_SDK_OK, name);
    char *flags = concat("{\"cert\":\"", cert, "\",\"key\":\"", key, "\"}");
    char *xml = json_token(built, "xml");
    char *sign = concat("{\"command\":\"sign\",\"flags\":", flags, ",\"input\":{\"xml\":", xml, "}}");
    char *signed_out = call(sign, SUNAT_SDK_OK, name);
    char *vector = read_file(concat(repo, "/tests/vectors/", name, ".signed.xml", NULL));
    if (strcmp(json_plain(signed_out, "digest_value"), element_text(vector, "ds:DigestValue")) != 0)
        fail(name, "DigestValue differs from the vector");
    if (strcmp(json_plain(signed_out, "signature_value"), element_text(vector, "ds:SignatureValue")) != 0)
        fail(name, "SignatureValue differs from the vector");
    if (dump) {
        write_file(concat(dump, "/", name, ".build.json", NULL), built);
        write_file(concat(dump, "/", name, ".sign.json", NULL), signed_out);
    }
    free(fixture);
    free(built);
    free(flags);
    free(xml);
    free(sign);
    free(signed_out);
    free(vector);
}

int main(int argc, char **argv) {
    const char *repo, *dump = NULL;
    char *cert, *key, *bad;
    int first = 2, i;
    if (argc < 3) {
        fprintf(stderr, "usage: battery <repository> [--dump <directory>] <case>...\n");
        return 2;
    }
    if (argc > 4 && strcmp(argv[2], "--dump") == 0) {
        dump = argv[3];
        first = 4;
    }
    load();
    if ((uint32_t)f_abi() != SUNAT_SDK_ABI_VERSION) fail("abi version", NULL);
    bad = call("{\"command\":\"nope\",\"input\":{}}", SUNAT_SDK_ERROR, "unknown command");
    if (strncmp(bad, "{\"error\":\"usage: sunat-sdk", 26) != 0) fail("error shape", bad);
    free(bad);
    /* Invalid UTF-8 (an ANSI n with tilde) is refused, never misread. */
    bad = call("{\"command\":\"build\",\"input\":{\"x\":\"\xf1\"}}", SUNAT_SDK_ERROR, "ANSI request");
    if (!strstr(bad, "UTF-8")) fail("ANSI request: message", bad);
    free(bad);

    repo = argv[1];
    cert = json_escape(concat(repo, "/tests/vectors/test-cert/test-cert.pem", NULL, NULL, NULL));
    key = json_escape(concat(repo, "/tests/vectors/test-cert/test-key.pem", NULL, NULL, NULL));
    for (i = first; i < argc; i++) run_case(repo, cert, key, dump, argv[i]);
    printf("ok: %d cases through the %s declarations, %d-bit (sdk %s, abi %u)\n", argc - first, LEGACY_LANGUAGE,
           (int)(sizeof(void *) * 8), (const char *)(uintptr_t)f_version(), (unsigned)f_abi());
    return 0;
}
